class _B031Controller extends _RecordingLibraryController {
  _B031Controller({
    super.currentPath,
    super.tracks,
  });

  /// Imperatively update `currentPath` and fan out a notification — the
  /// LibraryController listener inside [VoidScreen] rebuilds the crumb.
  void simulatePathChange(String? next) {
    currentPath = next;
    notifyListeners();
  }
}

edits.newText:
class _B031Controller extends _RecordingLibraryController {
  _B031Controller({
    required String? currentPath,
    required List<AudioTrack> Function(String? currentPath) tracksForPath,
  })  : _tracksForPath = tracksForPath,
        super(
          currentPath: currentPath,
          tracks: tracksForPath(currentPath),
        );

  final List<AudioTrack> Function(String? currentPath) _tracksForPath;

  /// Imperatively update `currentPath` and its derived `tracks` so
  /// [VoidScreen] can re-evaluate viewport visibility.
  void simulatePathChange(String? next) {
    currentPath = next;
    tracks = List<AudioTrack>.from(_tracksForPath(next));
    notifyListeners();
  }
}

